package com.gathin.tvhome;import android.content.Context;import android.util.Log;org.json.JSONArray;org.json.JSONObject;import java.io.File;import java.io.FileOutputStream;import java.io.InputStream;import java.net.HttpURLConnection;import java.net.URL;import java.nio.charset.StandardCharsets;public final class WallpaperFetcher {public interface Callback {void onComplete(boolean success, String message);}public static void fetchFromReddit(Context context, Callback callback) {new Thread(() -> {try {URL url = new URL("https://www.reddit.com/r/wallpapers/hot.json?limit=25");HttpURLConnection conn = (HttpURLConnection) url.openConnection();conn.setRequestProperty("User-Agent", "Android:com.gathin.tvhome:v3.2");if (conn.getResponseCode() != 200) {callback.onComplete(false, "Reddit HTTP error");return;}InputStream in = conn.getInputStream();byte[] buf = new byte[64 * 1024];int n = 0, r;while ((r = in.read(buf, n, buf.length - n)) > 0) n += r;String jsonStr = new String(buf, 0, n, StandardCharsets.UTF_8);in.close();JSONObject root = new JSONObject(jsonStr);JSONArray children = root.getJSONObject("data").getJSONArray("children");File dir = Config.dir(context);File wallpapersDir = new File(dir, "wallpapers");if (!wallpapersDir.exists()) wallpapersDir.mkdirs();int downloaded = 0;for (int i = 0; i < children.length(); i++) {JSONObject post = children.getJSONObject(i).getJSONObject("data");String imgUrl = post.optString("url_overridden_by_dest", post.optString("url", ""));if (!imgUrl.endsWith(".jpg") && !imgUrl.endsWith(".png")) continue;File outFile = new File(wallpapersDir, "reddit_" + System.currentTimeMillis() + "_" + i + ".jpg");if (downloadImage(imgUrl, outFile)) {downloaded++;if (downloaded >= 5) break;}}callback.onComplete(downloaded > 0, downloaded > 0 ? "Downloaded " + downloaded + " Reddit wallpapers!" : "No images found.");}catch (Exception e) {callback.onComplete(false, "Error: " + e.getMessage());}}).start();}private static boolean downloadImage(String urlStr, File outFile) {try {HttpURLConnection conn = (HttpURLConnection) new URL(urlStr).openConnection();InputStream in = conn.getInputStream();FileOutputStream out = new FileOutputStream(outFile);byte[] buf = new byte[8192];int len;while ((len = in.read(buf)) != -1) out.write(buf, 0, len);out.close();in.close();return outFile.isFile() && outFile.length() > 10 * 1024;}catch (Exception e) {return false;}}}
